/*
 * ==========================================================================
 * UVa 10200 - Prime Time
 * Title-CN: 尤拉質數公式生成比例
 * Difficulty: UVa Star 2
 * Tags: math, number-theory, prime
 * ==========================================================================
 * [EN] Problem: Calculate percentage of primes generated by Euler's n^2 + n + 41 in range [a, b].
 * [中文] 題目說明: 計算區間 [a, b] 內，尤拉公式 n^2 + n + 41 產生質數的百分比。
 * [EN] Approach: Precompute prefix sums of prime counts up to 10000.
 * [中文] 思路: 前綴和陣列預處理 0~10000 每個 n 是否為質數，O(1) 回答區間查詢。
 * ==========================================================================
 */
#include <stdio.h>

static int is_prime(int n) {
    int divisor;
    if (n < 2) return 0;
    if (n % 2 == 0) return n == 2;
    for (divisor = 3; divisor <= n / divisor; divisor += 2) {
        if (n % divisor == 0) return 0;
    }
    return 1;
}

int solve(FILE *in, FILE *out) {
    int prefix[10001];
    int a;
    int b;
    int n;

    prefix[0] = is_prime(41);
    for (n = 1; n <= 10000; ++n) {
        prefix[n] = prefix[n - 1] + is_prime(n * n + n + 41);
    }

    while (fscanf(in, "%d %d", &a, &b) == 2) {
        int count;
        int total;
        double percentage;
        if (a > b) {
            int temp = a;
            a = b;
            b = temp;
        }
        count = prefix[b] - (a == 0 ? 0 : prefix[a - 1]);
        total = b - a + 1;
        percentage = 100.0 * (double)count / (double)total;
        fprintf(out, "%.2f\n", percentage + 1e-9);
    }
    return 0;
}

int main(void) {
    return solve(stdin, stdout);
}
